  'st.header_title': 'Autenticación por cabecera HTTP',
  'st.header_intro': 'Solo se usa cuando la autenticación es «Cabecera HTTP». Un proxy inverso o una pasarela de inicio de sesión único autentica a los usuarios y pasa el nombre de usuario en una cabecera; pgkiln solo confía en ella desde las direcciones de proxy de {env}',
