  'st.header_name_help': 'La cabecera de la petición con el nombre de usuario (APEX: HTTP Header Variable). Vacío: X-Remote-User. Una cabecera cambiada o ausente termina la sesión.',
  'st.logout_url': 'URL de cierre de sesión',
  'st.logout_url_ph': 'p. ej. https://sso.example.com/logout',
  'st.logout_url_help': 'Adónde lleva «Cerrar sesión» al terminar la sesión, normalmente la página de cierre de sesión del propio proxy. Vacío: una página de «sesión cerrada».',
  'st.header_auto': 'Crear cuentas automáticamente',
  'st.header_auto_help': 'Un nombre de usuario desconocido recibe una cuenta nueva con acceso a esta aplicación. Si no, la cuenta debe existir y tener acceso.',
  'st.db_title': 'Cuentas de base de datos',
  'st.db_intro': 'Solo se usa cuando la autenticación es «Cuentas de base de datos». Los usuarios inician sesión con un rol de inicio de sesión de PostgreSQL y su contraseña, comprobados con una breve conexión a esta base de datos con ese rol. Los superusuarios y los roles propios de pgkiln siempre se rechazan; sin ninguno de los dos campos nadie puede iniciar sesión.',
  'st.db_roles': 'Roles permitidos',
  'st.db_roles_ph': 'p. ej. alice, bob',
  'st.db_roles_help': 'Roles de inicio de sesión que pueden entrar, separados por comas (nombres exactos).',
  'st.db_member': 'O miembros del rol',
  'st.db_member_ph': 'p. ej. app_users_group',
  'st.db_member_help': 'Todos los miembros de este rol también pueden iniciar sesión.',
  'st.custom_title': 'Autenticación personalizada',
  'st.custom_intro': 'Solo se usa cuando la autenticación es «Personalizada». Su propio PL/pgSQL comprueba el nombre de usuario y la contraseña del formulario, con el rol de base de datos de la aplicación; la contraseña se pasa como parámetro y nunca se registra. Los intentos fallidos se limitan como otros inicios de sesión. Sin ninguno de los dos campos nadie puede iniciar sesión.',
  'st.custom_fn': 'Nombre de la función',
  'st.custom_fn_ph': 'p. ej. app.check_login',
  'st.custom_fn_help': 'Una función (p_username text, p_password text) returns boolean, en minúsculas, opcionalmente con su esquema. El rol de la aplicación necesita EXECUTE sobre ella. Tiene prioridad sobre el cuerpo de abajo.',
  'st.custom_body': 'O cuerpo de la función',
  'st.custom_body_help': 'PL/pgSQL con p_username y p_password que devuelve true para un inicio de sesión válido, p. ej. {example}',
  'st.custom_post': 'Código posterior a la autenticación',
  'st.custom_post_help': 'PL/pgSQL opcional que se ejecuta tras una comprobación correcta, con p_username (y meta.app_user()), p. ej. para registrar el último inicio de sesión. Lanzar una excepción rechaza el inicio de sesión. Los procesos de aplicación «after login» se ejecutan después como siempre.',
